/* ============ 提问箱：iOS 6 拟物风抽屉（基于 @collapse，点标题栏开合） ============ */
.xt-collapse-1 {
    background: linear-gradient(to bottom, #fdfdfd, #f0f0f0) !important;
    border: 1px solid #adadad !important;
    border-radius: 6px !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1), inset 0 1px 0 #fff !important;
    overflow: hidden;
}
.xt-collapse-1 .xt-collapse-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: linear-gradient(to bottom, #f5f5f5, #e0e0e0) !important;
