}
.xt-collapse-1 .xt-collapse-arrow { color: #555; }
.xt-collapse-1 .xt-collapse-body { overflow: hidden; }

/* 提问：便签纸 + 胶带 + 红色 Q 徽章（略微歪斜，像贴上去的） */
.xt-collapse-1 .xt-quote {
    position: relative;
    background: linear-gradient(to bottom, #fffef2, #fbf3cc) !important;
    border: 1px solid #d4cca1 !important;
    border-radius: 2px 2px 14px 2px !important;
