    text-align: right !important;
    color: #868e95 !important;
}
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6::before { background: #9aa2a8; box-shadow: 0 0 0 2px rgba(154,162,168,.2); }
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6::after { background: linear-gradient(to left, #d3d7da, rgba(211,215,218,0)); }

.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL1,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL2,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL3,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL4,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL5,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL6 {
    position: relative;
    display: block;
    box-sizing: border-box;
    width: 80%;
    margin-top: 3px !important; margin-bottom: 2px !important;
    padding: 4px 6px 8px !important;
    background: none !important; border: 0 !important; box-shadow: none !important; border-radius: 0 !important;
    font-size: 13.5px !important; line-height: 1.9 !important; font-weight: 400 !important;
