}
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL2,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL4,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL6 {
    margin-left: auto !important; margin-right: 20px !important;
    padding-right: 22px !important;
    text-align: right !important;
    color: #4a5056 !important;
}
/* 大引号作装饰：左边是开引号，右边是收引号 */
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL1::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL3::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL5::before {
