.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL2::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL4::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterL6::before {
